            size_t n = strlen(src);
            while (n > 0 && src[n - 1] == '/') n--;
            if (n >= 10 && strncmp(src + n - 10, "/resources", 10) == 0) n -= 10;
            while (n > 0 && src[n - 1] == '/') n--;
            if (n >= sizeof(res_root)) n = sizeof(res_root) - 1;
